<%= form_with model: [ :moderate, quiz ] do |f| %>
  <% if quiz.errors.any? %>
    <div class="errors">
      <% if quiz.errors.count == 1 %>
        <%= quiz.errors.full_messages.first %>
      <% else %>
        <ul>
          <% quiz.errors.full_messages.each do |msg| %>
            <li><%= msg %></li>
          <% end %>
        </ul>
      <% end %>
    </div>
  <% end %>

  <div class="field">
    <%= f.label :title, "Title", class: "field-label" %>
    <%= f.text_field :title, class: "input", required: true, autofocus: true %>
  </div>

  <div class="field">
    <%= f.label :number_of_winners, "Number of winners", class: "field-label" %>
    <%= f.number_field :number_of_winners, class: "input input--number", min: 1, step: 1, required: true %>
  </div>

  <div class="field-row">
    <div class="field">
      <%= f.label :timer_minutes, "Timer minutes", class: "field-label" %>
      <%= f.number_field :timer_minutes, class: "input input--number", min: 0, step: 1, required: true %>
    </div>

    <div class="field">
      <%= f.label :timer_seconds, "Timer seconds", class: "field-label" %>
      <%= f.number_field :timer_seconds, class: "input input--number", min: 0, max: 59, step: 1, required: true %>
    </div>
  </div>

  <div class="buttons">
    <button type="submit" class="btn btn--pink">Save quiz</button>
    <%= link_to "Cancel", quiz.persisted? ? moderate_quiz_path(quiz) : moderate_root_path, class: "btn btn--ghost" %>
  </div>
<% end %>
EOF

