            <div class="stage-question__num">Question <%= @state[:question_number] %> of <%= @state[:total_questions] %></div>
            <% if @state[:timer_duration_seconds].to_i.positive? && !@state[:timer_remaining_ms].nil? %>
              <div class="stage-timer" data-moderator-game-target="timer"><%= format_countdown_ms(@state[:timer_remaining_ms], @state[:timer_duration_seconds]) %></div>
            <% end %>
          </div>
          <div class="stage-question__body"><%= @state[:question_body] %></div>
          <ol class="stage-options">
            <% @state[:options].each do |opt| %>
              <li class="stage-option">
                <span class="stage-option__letter" aria-hidden="true"><%= opt[:letter] %></span>
                <span class="stage-option__title"><%= opt[:body] %></span>
              </li>
            <% end %>
          </ol>
        </div>
      <% elsif @state[:status] == "question_closed" %>
        <div>
          <div class="stage-question__head">
            <div class="stage-question__num">Question <%= @state[:question_number] %> of <%= @state[:total_questions] %></div>
          </div>
          <div class="stage-question__body"><%= @state[:question_body] %></div>
          <ol class="stage-options stage-options--results">
            <% @state[:options].each do |opt| %>
              <li class="stage-option <%= 'is-correct' if opt[:correct] %>">
                <span class="stage-option__bar" style="--share: <%= opt[:share] %>%"></span>
                <span class="stage-option__letter" aria-hidden="true"><%= opt[:letter] %></span>
                <span class="stage-option__title"><%= opt[:body] %></span>
                <% if opt[:correct] %>
                  <span class="stage-option__mark">Correct</span>
                <% end %>
                <span class="stage-option__count"><%= opt[:count] %></span>
              </li>
            <% end %>
          </ol>
        </div>
      <% else %>
        <div class="leaderboard-layout">
          <div>
            <div class="screen__kicker"><%= @state[:quiz_title] %></div>
            <h1 class="leaderboard-layout__title">The quiz is over</h1>
          </div>
          <ol class="leaderboard" data-moderator-game-target="leaderboard">
            <% (@state[:leaderboard] || []).each do |entry| %>
              <li class="leader <%= 'is-winner' if entry[:winner] %>">
                <span class="leader__place"><%= entry[:place] %></span>
                <span class="leader__name"><%= entry[:name] %><% if entry[:winner] %> <span class="leader__badge">Winner</span><% end %></span>
                <span class="leader__score"><%= pluralize(entry[:points], "point") %></span>
              </li>
            <% end %>
          </ol>
        </div>
      <% end %>
    </div>
  </div>

  <div class="screen-controls">
    <div class="screen-controls__info">
      <%= link_to "← Back to quiz", moderate_quiz_path(@quiz) %>
      <span data-moderator-game-target="infoExtra">
        <% if @state[:status] == "question_open" %>
          <span class="answers-counter" data-moderator-game-target="answersCounter">Answers: <%= @state[:answered_count] %> / <%= @state[:online_players_count] %></span>
        <% end %>
      </span>
    </div>

    <div class="buttons" data-moderator-game-target="actionArea">
      <% if @state[:status] == "lobby" %>
        <%= form_with url: start_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false, action: "submit->moderator-game#submitAction" } do %>
          <button type="submit" class="btn btn--pink btn--lg">Start</button>
        <% end %>
      <% elsif @state[:status] == "question_open" %>
        <%= form_with url: finish_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false, action: "submit->moderator-game#submitAction" } do %>
          <button type="submit" class="btn btn--pink btn--lg">Finish</button>
        <% end %>
      <% elsif @state[:status] == "question_closed" %>
        <% if @state[:is_last_question] %>
          <%= form_with url: end_quiz_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false, action: "submit->moderator-game#submitAction" } do %>
            <button type="submit" class="btn btn--pink btn--lg">End quiz</button>
          <% end %>
        <% else %>
          <%= form_with url: next_question_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false, action: "submit->moderator-game#submitAction" } do %>
            <button type="submit" class="btn btn--pink btn--lg">Next</button>
          <% end %>
        <% end %>
      <% elsif @state[:status] == "finished" %>
        <%= form_with url: pick_top_winners_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false, action: "submit->moderator-game#submitAction" } do %>
          <button type="submit" class="btn btn--pink btn--lg">Top <%= winners_n %></button>
        <% end %>
        <%= form_with url: draw_winners_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false, action: "submit->moderator-game#submitAction" } do %>
          <button type="submit" class="btn btn--light btn--lg">Draw</button>
        <% end %>
        <%= form_with url: reset_winners_moderate_quiz_game_path(@quiz, @game), method: :post, data: { turbo: false, action: "submit->moderator-game#submitAction" } do %>
          <button type="submit" class="btn btn--light">Reset winners</button>
        <% end %>
      <% end %>
    </div>
  </div>
</section>
EOF

cat <<'EOF' > app/javascript/controllers/moderator_game_controller.js
import { Controller } from "@hotwired/stimulus"
import { createConsumer } from "@rails/actioncable"

export default class extends Controller {
  static targets = [
    "topTitle",
    "stage",
    "playersCounter",
    "infoExtra",
    "answersCounter",
    "actionArea",
    "leaderboard",
    "timer"
  ]

  static values = [
  ]

  static values = {
    gameId: Number,
    moderatorToken: String,
    stateUrl: String,
    startUrl: String,
    finishUrl: String,
    nextUrl: String,
    endUrl: String,
    pickTopUrl: String,
    drawUrl: String,
    resetWinnersUrl: String,
    numberOfWinners: Number,
    status: String,
    gameQuestionId: Number,
    timerDurationSeconds: Number,
    timerRemainingMs: Number,
    version: Number
  }

  connect() {
    this.wsConnected = false
    this.hasConnectedOnce = false
    this.renderedVersion = this.versionValue
    this.actionQueue = Promise.resolve()
    this.countdownInterval = null
    this.expiryFallbackTimeout = null
    this.timerTargetPerfNow = null
    this.activeTimerDuration = 0
    this.activeTimerGqId = null

    if (this.statusValue === "question_open" && this.timerDurationSecondsValue > 0 && this.timerRemainingMsValue >= 0) {
      this.startCountdown(this.timerRemainingMsValue, this.timerDurationSecondsValue, this.gameQuestionIdValue)
    }

    this.setupCable()

    this.onVisibilityOrOnline = () => {
      if (document.visibilityState === "visible") {
        this.fetchState()
      }
    }
    this.onPageLeave = () => {
      this.teardownCable()
    }
    this.onPageShow = (event) => {
      if (event.persisted) {
        this.setupCable()
        this.fetchState()
      }
    }

    document.addEventListener("visibilitychange", this.onVisibilityOrOnline)
    window.addEventListener("online", this.onVisibilityOrOnline)
    window.addEventListener("pagehide", this.onPageLeave)
    window.addEventListener("beforeunload", this.onPageLeave)
    window.addEventListener("pageshow", this.onPageShow)

    this.pollTimer = setInterval(() => {
      if (!this.wsConnected) {
        this.fetchState()
      }
    }, 2000)
  }

  disconnect() {
    if (this.pollTimer) clearInterval(this.pollTimer)
    this.stopCountdown()
    document.removeEventListener("visibilitychange", this.onVisibilityOrOnline)
    window.removeEventListener("online", this.onVisibilityOrOnline)
    window.removeEventListener("pagehide", this.onPageLeave)
    window.removeEventListener("beforeunload", this.onPageLeave)
    window.removeEventListener("pageshow", this.onPageShow)
    this.teardownCable()
  }

  setupCable() {
    if (this.subscription) return
    this.consumer = createConsumer()
    this.subscription = this.consumer.subscriptions.create(
      {
        channel: "GameModeratorChannel",
        game_id: this.gameIdValue,
        moderator_token: this.moderatorTokenValue
      },
      {
        connected: () => {
          const reconnected = this.hasConnectedOnce
          this.wsConnected = true
          this.hasConnectedOnce = true
          if (reconnected) {
            this.fetchState()
          }
        },
        disconnected: () => {
          this.wsConnected = false
        },
        received: (data) => {
          this.handleMessage(data)
        }
      }
    )
  }

  teardownCable() {
    this.wsConnected = false
    if (this.subscription) {
      this.subscription.unsubscribe()
      this.subscription = null
    }
    if (this.consumer) {
      this.consumer.disconnect()
      this.consumer = null
    }
  }

  submitAction(event) {
    event.preventDefault()
    const form = event.currentTarget
    const actionUrl = form.action

    this.actionQueue = this.actionQueue.then(async () => {
      try {
        const response = await fetch(actionUrl, {
          method: "POST",
          headers: {
            Accept: "application/json",
            "X-CSRF-Token": this.csrfToken()
          },
          credentials: "same-origin"
        })
        if (response.ok) {
          const state = await response.json()
          this.applyState(state)
        }
      } catch (_err) {
        await this.fetchState()
      }
    })
  }

  async fetchState() {
    try {
      const response = await fetch(this.stateUrlValue, {
        headers: { Accept: "application/json" },
        credentials: "same-origin",
        cache: "no-store"
      })
      if (response.ok) {
        const state = await response.json()
        this.applyState(state)
      }
    } catch (_err) {
      // Transient conference Wi-Fi error; next WS frame or poll will sync
    }
  }

  handleMessage(data) {
    if (!data) return

    if (data.type === "counters") {
      if (data.state_version && data.state_version < this.versionValue) return
      if (data.status && data.status !== this.statusValue) {
        this.fetchState()
        return
      }
      if (data.state_version) this.versionValue = data.state_version
      this.updateCountersInPlace(data)
      return
    }

    if (data.type === "state") {
      this.applyState(data)
    }
  }

  applyState(state) {
    if (!state) return
    if (state.state_version && state.state_version < this.versionValue) return

    const prevStatus = this.statusValue
    const prevGqId = this.gameQuestionIdValue
    const nextGqId = state.game_question_id || 0
    const prevWinnersN = this.numberOfWinnersValue

    if (state.state_version && state.state_version > this.versionValue) {
      this.versionValue = state.state_version
    }
    if (state.number_of_winners) {
      this.numberOfWinnersValue = state.number_of_winners
    }

    if (state.status === prevStatus && nextGqId === prevGqId) {
      if (state.status === "finished") {
        const winnersCountChanged = Boolean(state.number_of_winners && state.number_of_winners !== prevWinnersN)
        if (this.renderedVersion !== state.state_version) {
          this.renderedVersion = state.state_version
          this.renderLeaderboardInPlace(state)
        }
        if (winnersCountChanged) {
          this.renderControls(state)
        }
      } else if (state.status === "question_open") {
        this.updateCountersInPlace(state)
        if (state.timer_duration_seconds > 0 && state.timer_remaining_ms != null) {
          if (!this.hasTimerTarget) {
            this.renderStage(state)
          }
          this.startCountdown(state.timer_remaining_ms, state.timer_duration_seconds, nextGqId)
        } else {
          this.stopCountdown()
        }
      } else {
        this.updateCountersInPlace(state)
      }
      return
    }

    this.stopCountdown()
    this.statusValue = state.status
    this.gameQuestionIdValue = nextGqId
    this.renderedVersion = state.state_version || this.versionValue

    const isCalm = state.status !== "lobby"
    const isQuestionPhase = state.status === "question_open" || state.status === "question_closed"
    this.element.classList.toggle("cover--calm", isCalm)
    if (this.hasTopTitleTarget) {
      this.topTitleTarget.textContent = isQuestionPhase ? state.quiz_title : ""
    }

    this.renderStage(state)
    this.renderControls(state)

    if (state.status === "question_open" && state.timer_duration_seconds > 0 && state.timer_remaining_ms != null) {
      this.startCountdown(state.timer_remaining_ms, state.timer_duration_seconds, nextGqId)
    }
  }

  startCountdown(remainingMs, durationSeconds, gqId) {
    const dur = Number(durationSeconds || 0)
    const rem = Math.max(0, Number(remainingMs || 0))
    const candidateTarget = performance.now() + rem

    if (this.activeTimerGqId === gqId && this.timerTargetPerfNow !== null && Math.abs(candidateTarget - this.timerTargetPerfNow) < 500) {
      this.timerTargetPerfNow = Math.min(this.timerTargetPerfNow, candidateTarget)
    } else {
      this.timerTargetPerfNow = candidateTarget
    }

    this.activeTimerDuration = dur
    this.activeTimerGqId = gqId

    if (this.expiryFallbackTimeout) {
      clearTimeout(this.expiryFallbackTimeout)
      this.expiryFallbackTimeout = null
    }

    this.updateTimerDom()

    if (!this.countdownInterval) {
      this.countdownInterval = setInterval(() => {
        this.updateTimerDom()
      }, 100)
    }
  }

  stopCountdown() {
    if (this.countdownInterval) {
      clearInterval(this.countdownInterval)
      this.countdownInterval = null
    }
    if (this.expiryFallbackTimeout) {
      clearTimeout(this.expiryFallbackTimeout)
      this.expiryFallbackTimeout = null
    }
    this.timerTargetPerfNow = null
    this.activeTimerDuration = 0
    this.activeTimerGqId = null
  }

  updateTimerDom() {
    if (this.statusValue !== "question_open" || this.timerTargetPerfNow === null) {
      this.stopCountdown()
      return
    }

    const remainingMs = Math.max(0, this.timerTargetPerfNow - performance.now())
    const formatted = this.formatCountdownMs(remainingMs, this.activeTimerDuration)

    if (this.hasTimerTarget && this.timerTarget.textContent !== formatted) {
      this.timerTarget.textContent = formatted
    }

    if (remainingMs <= 0 && !this.expiryFallbackTimeout) {
      const expiredGqId = this.activeTimerGqId
      this.expiryFallbackTimeout = setTimeout(() => {
        this.expiryFallbackTimeout = null
        if (this.statusValue === "question_open" && this.gameQuestionIdValue === expiredGqId) {
          this.fetchState()
        }
      }, 120)
    }
  }

  formatCountdownMs(remainingMs, durationSeconds) {
    const maxSec = Math.max(0, Number(durationSeconds || 0))
    const rem = Number(remainingMs || 0)
    const sec = rem <= 0 ? 0 : Math.min(maxSec, Math.ceil(rem / 1000))
    const minutes = Math.floor(sec / 60)
    const seconds = sec % 60
    return `${minutes}:${String(seconds).padStart(2, "0")}`
  }

  updateCountersInPlace(data) {
    if (this.statusValue === "lobby" && this.hasPlayersCounterTarget) {
      this.playersCounterTarget.textContent = `Players: ${data.online_players_count}`
    } else if (this.statusValue === "question_open" && this.hasAnswersCounterTarget) {
      this.answersCounterTarget.textContent = `Answers: ${data.answered_count} / ${data.online_players_count}`
    }
  }

  renderLeaderboardInPlace(state) {
    if (this.hasLeaderboardTarget) {
      this.buildLeaderboardItems(this.leaderboardTarget, state.leaderboard || [])
    } else {
      this.renderStage(state)
    }
  }

  renderStage(state) {
    this.stageTarget.replaceChildren()

    if (state.status === "question_open" || state.status === "question_closed") {
      const wrapper = document.createElement("div")

      const headEl = document.createElement("div")
      headEl.className = "stage-question__head"

      const numEl = document.createElement("div")
      numEl.className = "stage-question__num"
      numEl.textContent = `Question ${state.question_number} of ${state.total_questions}`
      headEl.appendChild(numEl)

      if (state.status === "question_open" && state.timer_duration_seconds > 0 && state.timer_remaining_ms != null) {
        const timerEl = document.createElement("div")
        timerEl.className = "stage-timer"
        timerEl.dataset.moderatorGameTarget = "timer"
        timerEl.textContent = this.formatCountdownMs(state.timer_remaining_ms, state.timer_duration_seconds)
        headEl.appendChild(timerEl)
      }

      wrapper.appendChild(headEl)

      const bodyEl = document.createElement("div")
      bodyEl.className = "stage-question__body"
      bodyEl.textContent = state.question_body
      wrapper.appendChild(bodyEl)

      const listEl = document.createElement("ol")
      listEl.className = state.status === "question_closed" ? "stage-options stage-options--results" : "stage-options"

      for (const opt of state.options || []) {
        const li = document.createElement("li")
        li.className = state.status === "question_closed" && opt.correct ? "stage-option is-correct" : "stage-option"

        if (state.status === "question_closed") {
          const bar = document.createElement("span")
          bar.className = "stage-option__bar"
          bar.style.setProperty("--share", `${opt.share || 0}%`)
          li.appendChild(bar)
        }

        const letter = document.createElement("span")
        letter.className = "stage-option__letter"
        letter.setAttribute("aria-hidden", "true")
        letter.textContent = opt.letter
        li.appendChild(letter)

        const title = document.createElement("span")
        title.className = "stage-option__title"
        title.textContent = opt.body
        li.appendChild(title)

        if (state.status === "question_closed") {
          if (opt.correct) {
            const mark = document.createElement("span")
            mark.className = "stage-option__mark"
            mark.textContent = "Correct"
            li.appendChild(mark)
          }

          const count = document.createElement("span")
          count.className = "stage-option__count"
          count.textContent = String(opt.count ?? 0)
          li.appendChild(count)
        }

        listEl.appendChild(li)
      }

      wrapper.appendChild(listEl)
      this.stageTarget.appendChild(wrapper)
    } else if (state.status === "finished") {
      const layout = document.createElement("div")
      layout.className = "leaderboard-layout"

      const left = document.createElement("div")
      const kicker = document.createElement("div")
      kicker.className = "screen__kicker"
      kicker.textContent = state.quiz_title
      left.appendChild(kicker)

      const heading = document.createElement("h1")
      heading.className = "leaderboard-layout__title"
      heading.textContent = "The quiz is over"
      left.appendChild(heading)
      layout.appendChild(left)

      const listEl = document.createElement("ol")
      listEl.className = "leaderboard"
      listEl.dataset.moderatorGameTarget = "leaderboard"
      this.buildLeaderboardItems(listEl, state.leaderboard || [])
      layout.appendChild(listEl)

      this.stageTarget.appendChild(layout)
    }
  }

  buildLeaderboardItems(listEl, leaderboard) {
    listEl.replaceChildren()
    for (const entry of leaderboard) {
      const li = document.createElement("li")
      li.className = entry.winner ? "leader is-winner" : "leader"

      const place = document.createElement("span")
      place.className = "leader__place"
      place.textContent = String(entry.place)
      li.appendChild(place)

      const name = document.createElement("span")
      name.className = "leader__name"
      name.appendChild(document.createTextNode(entry.name))
      if (entry.winner) {
        name.appendChild(document.createTextNode(" "))
        const badge = document.createElement("span")
        badge.className = "leader__badge"
        badge.textContent = "Winner"
        name.appendChild(badge)
      }
      li.appendChild(name)

      const score = document.createElement("span")
      score.className = "leader__score"
      score.textContent = this.formatPoints(entry.points)
      li.appendChild(score)

      listEl.appendChild(li)
    }
  }

  formatPoints(points) {
    const pts = Number(points ?? 0)
    return `${pts} ${pts === 1 ? "point" : "points"}`
  }

  renderControls(state) {
    this.infoExtraTarget.replaceChildren()
    this.actionAreaTarget.replaceChildren()

    if (state.status === "question_open") {
      const counter = document.createElement("span")
      counter.className = "answers-counter"
      counter.dataset.moderatorGameTarget = "answersCounter"
      counter.textContent = `Answers: ${state.answered_count} / ${state.online_players_count}`
      this.infoExtraTarget.appendChild(counter)

      this.actionAreaTarget.appendChild(this.buildActionForm(this.finishUrlValue, "Finish"))
    } else if (state.status === "question_closed") {
      if (state.is_last_question) {
        this.actionAreaTarget.appendChild(this.buildActionForm(this.endUrlValue, "End quiz"))
      } else {
        this.actionAreaTarget.appendChild(this.buildActionForm(this.nextUrlValue, "Next"))
      }
    } else if (state.status === "finished") {
      const n = state.number_of_winners || this.numberOfWinnersValue || 3
      this.actionAreaTarget.appendChild(this.buildActionForm(this.pickTopUrlValue, `Top ${n}`, "btn btn--pink btn--lg"))
      this.actionAreaTarget.appendChild(this.buildActionForm(this.drawUrlValue, "Draw", "btn btn--light btn--lg"))
      this.actionAreaTarget.appendChild(this.buildActionForm(this.resetWinnersUrlValue, "Reset winners", "btn btn--light"))
    }
  }

  buildActionForm(actionUrl, labelText, buttonClass = "btn btn--pink btn--lg") {
    const form = document.createElement("form")
    form.action = actionUrl
    form.method = "post"
    form.dataset.turbo = "false"
    form.dataset.action = "submit->moderator-game#submitAction"

    const tokenInput = document.createElement("input")
    tokenInput.type = "hidden"
    tokenInput.name = "authenticity_token"
    tokenInput.value = this.csrfToken()
    form.appendChild(tokenInput)

    const button = document.createElement("button")
    button.type = "submit"
    button.className = buttonClass
    button.textContent = labelText
    form.appendChild(button)

    return form
  }

  csrfToken() {
    const meta = document.querySelector('meta[name="csrf-token"]')
    return meta ? meta.content : ""
  }
}
EOF

